n."}]}, {'group': 'Add mapping when root has no mapping', 'cases': [{'input': [{'parameter': 'currentDiscriminatorContext', 'value': 'ContextWithRootDiscriminatorNoMapping'}, {'parameter': 'discriminator', 'value': '{ "propertyName": "type" }'}, {'parameter': 'schema', 'value': '{ "schemaLocation": "/child", "schemaNode": { "discriminator": { "mapping": { "dog": { "$ref": "#/definitions/Dog" } } } } }'}, {'parameter': 'instanceLocation', 'value': '/instance'}], 'expected': 'Root discriminator now contains mapping { "dog": { "$ref": "#/definitions/Dog" } }; no exception thrown.', 'description': 'If the root discriminator lacks a "mapping" field but the nested schema provides one, the method should copy the entire mapping object to the root discriminator.'}]}, {'group': 'Merge mappings without conflict', 'cases': [{'input': [{'parameter': 'currentDiscriminatorContext', 'value': 'ContextWithRootMapping'}, {'parameter': 'discriminator', 'value': '{ "propertyName": "type", "mapping": { "cat": { "$ref": "#/definitions/Cat" } } }'}, {'parameter': 'schema', 'value': '{ "schemaLocation": "/child", "schemaNode": { "discriminator": { "mapping": { "dog": { "$ref": "#/definitions/Dog" }, "cat": { "$ref": "#/definitions/Cat" } } } } }'}, {'parameter': 'instanceLocation', 'value': '/instance'}], 'expected': 'Root mapping now contains both "cat" and "dog" entries; the existing "cat" entry is unchanged because the node reference is identical; no exception thrown.', 'description': 'When both root and child discriminators have mappings, the method should merge new keys and ignore keys that already exist with the same JsonNode instance.'}]}, {'group': 'Merge mappings with conflict throws', 'cases': [{'input': [{'parameter': 'currentDiscriminatorContext', 'value': 'ContextWithRootMappingConflict'}, {'parameter': 'discriminator', 'value': '{ "propertyName": "type", "mapping": { "cat": { "$ref": "#/definitions/OldCat" } } }'}, {'parameter': 'schema', 'value': '{ "schemaLocation": "/child"